fn disc(cx: i32, cy: i32, r: i32, c: i32) {
    let mut dy: i32 = 0 - r;
    while dy <= r {
        let mut hw: i32 = r;
        while hw * hw + dy * dy > r * r {
            hw = hw - 1;
        }
        host::display::fill_rect(cx - hw, cy + dy, hw * 2 + 1, 1, c);
        dy = dy + 1;
    }
}

fn frame(t: i32) {
    let tab = [0, 25, 49, 71, 90, 106, 117, 124, 127, 124, 117, 106, 90, 71, 49, 25, 0, -25, -49, -71, -90, -106, -117, -124, -127, -124, -117, -106, -90, -71, -49, -25];
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    host::display::clear(0x121216);
    let mut row: i32 = 0;
    while row < 8 {
        let mut col: i32 = 0;
        while col < 8 {
            let x: i32 = 40 + col * 62 + (row & 1) * 31;
            let y: i32 = 40 + row * 62;
            let r: i32 = 13 + tab[(t * 2 + col * 3 + row * 5) & 31] * 9 / 127;
            let c: i32 = if ((row + col) & 1) == 0 { 0x6fd0c2 } else { 0xd06f9d };
            disc(x, y, r, c);
            col = col + 1;
        }
        row = row + 1;
    }
    host::display::present();
}
